import XCTest
@testable import PokeTokenBar

/// A species' real PokéAPI values. The rows live in `SpeciesFactsData.swift`, generated by
/// `scripts/generate-species-facts.py`.
struct SpeciesFact: Sendable {
    let id: Int
    let slug: String
    let en: String
    let ko: String
    let height: Int
    let weight: Int
    let baseExperience: Int
    let genderRate: Int
    let types: [String]
    let stats: [Int]    // `PokemonStatCalculator.order`
    let captureRate: Int
    let isLegendary: Bool
    let isMythical: Bool
    let evolvesFromID: Int?
}

/// The only place a test gets a species' types, stats, gender ratio, size or names. A fixture that
/// answers for species X with species Y's numbers proves nothing about X and puts wrong facts in
/// screenshots, so an id outside the table fails the test instead of falling back to made-up data.
/// `SpeciesFactsGuardTests` rejects `PokemonDetails(` and `SpeciesIndexEntry(` anywhere else.
///
/// Absent data is allowed, wrong data is not: moves and abilities are not in the table and default to
/// none, and a test that needs them passes them in.
enum SpeciesFacts {
    static let regenerateCommand = "python3 scripts/generate-species-facts.py"
    static let byID = Dictionary(uniqueKeysWithValues: table.map { ($0.id, $0) })

    struct UnknownSpecies: Error, CustomStringConvertible {
        let id: Int
        var description: String { "species #\(id) is not in SpeciesFacts" }
    }

    static func fact(_ id: Int, file: StaticString = #filePath, line: UInt = #line) throws -> SpeciesFact {
        guard let fact = byID[id] else {
            XCTFail("Species #\(id) is not in SpeciesFacts. Add it to SPECIES_IDS in "
                    + "scripts/generate-species-facts.py and run `\(regenerateCommand)`.", file: file, line: line)
            throw UnknownSpecies(id: id)
        }
        return fact
    }

    static func details(_ id: Int, abilities: [PokemonAbilityOption] = [], moves: [PokemonMoveOption] = [],
                        file: StaticString = #filePath, line: UInt = #line) throws -> PokemonDetails {
        let fact = try fact(id, file: file, line: line)
        return PokemonDetails(
            speciesID: id, name: fact.slug, height: fact.height, weight: fact.weight,
            baseExperience: fact.baseExperience, genderRate: fact.genderRate, types: fact.types,
            baseStats: Dictionary(uniqueKeysWithValues: zip(PokemonStatCalculator.order, fact.stats).map { ($0, $1) }),
            abilities: abilities, moves: moves)
    }

    static func indexEntry(_ id: Int, file: StaticString = #filePath, line: UInt = #line) throws -> SpeciesIndexEntry {
        let fact = try fact(id, file: file, line: line)
        return SpeciesIndexEntry(id: id, names: ["en": fact.en, "ko": fact.ko], types: fact.types,
                                 captureRate: fact.captureRate, isLegendary: fact.isLegendary,
                                 isMythical: fact.isMythical, evolvesFromID: fact.evolvesFromID)
    }

    /// `["en": …, "ko": …]` in the shape `EvoLine.names` and `DexEntry.names` use.
    static func names(_ id: Int, file: StaticString = #filePath, line: UInt = #line) throws -> [String: String] {
        let fact = try fact(id, file: file, line: line)
        return ["en": fact.en, "ko": fact.ko]
    }

    /// Details that deliberately do not match any real species, for a test whose whole point is a value
    /// no species has (a corrupt save, a gender ratio the test must control, base HP 1 on a non-Shedinja).
    /// Try a real species that already has the property first: an always-female test wants a species
    /// whose `genderRate` is 8, not Slowpoke handed an 8. `reason` is for the reader and the grep.
    static func counterfactual(because reason: String, speciesID: Int, genderRate: Int = -1,
                               types: [String] = ["normal"], baseStats: [String: Int] = ["hp": 50],
                               abilities: [PokemonAbilityOption] = [], moves: [PokemonMoveOption] = []) -> PokemonDetails {
        precondition(!reason.isEmpty, "a counterfactual species needs a reason")
        return PokemonDetails(speciesID: speciesID, name: "counterfactual", height: 10, weight: 100,
                              baseExperience: nil, genderRate: genderRate, types: types, baseStats: baseStats,
                              abilities: abilities, moves: moves)
    }

    /// The index-entry counterpart of `counterfactual`: an id, graph shape or name no real species has.
    static func counterfactualIndexEntry(because reason: String, id: Int, names: [String: String],
                                         types: [String] = ["normal"], captureRate: Int = 255,
                                         isLegendary: Bool = false, evolvesFromID: Int? = nil) -> SpeciesIndexEntry {
        precondition(!reason.isEmpty, "a counterfactual species needs a reason")
        return SpeciesIndexEntry(id: id, names: names, types: types, captureRate: captureRate,
                                 isLegendary: isLegendary, isMythical: false, evolvesFromID: evolvesFromID)
    }
}
